#!/bin/sh
# Name: Disable Screensaver
# Author: arancool3000
# Icon: data:image/png;base64,
# DontUseFBInk

if lipc-set-prop com.lab126.powerd preventScreenSaver 1; then
	echo "Screensaver off. The screen will stay on."
	echo "Run Enable Screensaver, or reboot, to undo."
else
	echo "Failed. preventScreenSaver could not be set."
fi

exit 0
